styles:
.expandcard {
  position: relative;
  overflow: hidden;

  min-width: 60px;
  flex: 1 1 0;
  height: 400px;
  margin: 10px;

  border-radius: 30px;
  cursor: pointer;

  transition: flex-grow 0.5s cubic-bezier(0.05, 0.61, 0.41, 0.95),
              border-radius 0.5s cubic-bezier(0.05, 0.61, 0.41, 0.95),
              margin 0.5s cubic-bezier(0.05, 0.61, 0.41, 0.95);
}

.expandcard__bg {
  position: absolute;
  inset: 0;
  z-index: 0;
}

.expandcard__bg img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;

  transition: transform 0.5s cubic-bezier(0.05, 0.61, 0.41, 0.95);
}

.expandcard__hit {
  position: absolute;
  inset: 0;
  z-index: 3;
  display: block;
}

.expandcard__shadow {
  position: absolute;
  bottom: -40px;
  left: 0;
  right: 0;
  height: 120px;
  z-index: 1;

  box-shadow: inset 0 -120px 0px -120px black, inset 0 -120px 0px -100px black;

  transition: bottom 0.5s cubic-bezier(0.05, 0.61, 0.41, 0.95),
              box-shadow 0.5s cubic-bezier(0.05, 0.61, 0.41, 0.95);
}

.expandcard__label {
  display: flex;
  position: absolute;
  right: 0;
  bottom: 10px;
  left: 10px;
  z-index: 2;

  height: 40px;

  transition: bottom 0.5s cubic-bezier(0.05, 0.61, 0.41, 0.95),
              left 0.5s cubic-bezier(0.05, 0.61, 0.41, 0.95);
}

.expandcard__icon {
  display: flex;
  flex-direction: row;
  justify-content: center;
  align-items: center;

  min-width: 40px;
  max-width: 40px;
  height: 40px;
  border-radius: 100%;

  background-color: #fff;
  color: #5d9cec;
}

.expandcard__info {
  display: flex;
  flex-direction: column;
  justify-content: center;

  margin-left: 10px;
  color: #fff;
  white-space: pre;
}

.expandcard__info > div {
  position: relative;
  left: 20px;
  opacity: 0;

  transition: left 0.5s cubic-bezier(0.05, 0.61, 0.41, 0.95), opacity 0.5s ease-out;
}

.expandcard__title {
  font-weight: bold;
  font-size: 1.2rem;
}

.expandcard__subtitle {
  transition-delay: 0.1s;
}

/* Раскрытое состояние: по ховеру ИЛИ когда data-active="true" */
.expandcard:hover,
.expandcard[data-active="true"] {
  flex-grow: 10000;
  margin: 0;
  border-radius: 40px;
}

.expandcard:hover .expandcard__bg img,
.expandcard[data-active="true"] .expandcard__bg img {
  transform: scale(1.05);
}

.expandcard:hover .expandcard__shadow,
.expandcard[data-active="true"] .expandcard__shadow {
  bottom: 0;
  box-shadow: inset 0 -120px 120px -120px black, inset 0 -120px 120px -100px black;
}

.expandcard:hover .expandcard__label,
.expandcard[data-active="true"] .expandcard__label {
  bottom: 20px;
  left: 20px;
}

.expandcard:hover .expandcard__info > div,
.expandcard[data-active="true"] .expandcard__info > div {
  left: 0;
  opacity: 1;
}
